import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.regex.Pattern;

public class UserSearchServlet extends HttpServlet {

    private static final Pattern ALPHA_NUMERIC = Pattern.compile("^[a-zA-Z0-9_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String department = req.getParameter("dept");
        String sortField = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (department == null || department.isEmpty()) {
            resp.sendError(400, "Missing department parameter");
            return;
        }

        // Validate sort direction
        if (sortDir != null && !sortDir.equalsIgnoreCase("ASC") && !sortDir.equalsIgnoreCase("DESC")) {
            sortDir = "ASC";
        }

        // Validate sort field against allowlist
        if (sortField != null && !ALPHA_NUMERIC.matcher(sortField).matches()) {
            sortField = "last_name";
        }

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();
            stmt = conn.createStatement();

            // Build query - department is user-controlled and not parameterized
            String query = "SELECT employee_id, first_name, last_name, email, title " +
                          "FROM employees WHERE department = '" + department + "'";

            if (sortField != null) {
                query += " ORDER BY " + sortField + " " + sortDir;
            }

            rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                first = false;
                json.append("  {");
                json.append("\"id\":").append(rs.getInt("employee_id")).append(",");
                json.append("\"firstName\":\"").append(escapeJson(rs.getString("first_name"))).append("\",");
                json.append("\"lastName\":\"").append(escapeJson(rs.getString("last_name"))).append("\",");
                json.append("\"email\":\"").append(escapeJson(rs.getString("email"))).append("\",");
                json.append("\"title\":\"").append(escapeJson(rs.getString("title"))).append("\"");
                json.append("}");
            }

            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            // Log full error for debugging - includes query details
            System.err.println("SQL Error: " + e.getMessage());
            resp.sendError(500, "Database error occurred");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getProperty("db.url", "jdbc:postgresql://db-primary:5432/hrdb");
        String user = System.getProperty("db.user", "app_readonly");
        String pass = System.getProperty("db.pass", "");
        return DriverManager.getConnection(url, user, pass);
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private void closeQuietly(ResultSet rs, Statement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (SQLException ignored) {}
        try { if (stmt != null) stmt.close(); } catch (SQLException ignored) {}
        try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
    }
}
